function serializeFacets(rows) {
  if (!Array.isArray(rows) || rows.length !== Object.keys(rows).length) {
    throw new TypeError("rows must be a dense array");
  }

  const encode = (text) => {
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      if (
        (code >= 0xd800 && code <= 0xdbff &&
          (i + 1 >= text.length ||
            text.charCodeAt(i + 1) < 0xdc00 ||
            text.charCodeAt(i + 1) > 0xdfff)) ||
        (code >= 0xdc00 && code <= 0xdfff &&
          (i === 0 ||
            text.charCodeAt(i - 1) < 0xd800 ||
            text.charCodeAt(i - 1) > 0xdbff))
      ) {
        throw new URIError("Malformed UTF-16 surrogate");
      }
    }

    return encodeURIComponent(text).replace(/[!'()*]/g, (char) =>
      "%" + char.charCodeAt(0).toString(16).toUpperCase()
    );
  };

  const pairs = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];

    if (
      row === null ||
      typeof row !== "object" ||
      (Object.getPrototypeOf(row) !== Object.prototype &&
        Object.getPrototypeOf(row) !== null) ||
      typeof row.name !== "string" ||
      !Array.isArray(row.values) ||
      row.values.length !== Object.keys(row.values).length
    ) {
      throw new TypeError("Invalid row");
    }

    const encodedName = encode(row.name);

    for (let j = 0; j < row.values.length; j++) {
      if (typeof row.values[j] !== "string") {
        throw new TypeError("values must contain strings");
      }

      pairs.push([encodedName, encode(row.values[j])]);
    }
  }

  pairs.sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 :
    a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0
  );

  return pairs.map(([name, value]) => name + "=" + value).join("&");
}
